using Intranet.Entity;
namespace Intranet.Service;
public sealed class QualityEventService(IQualityEventRepository repository,GestionIdentity identity,RequestActor actor):ApplicationService(actor),IQualityEventService {
 public async Task<ServiceResult> Search(QualityEventFilter f,CancellationToken ct,bool unfinished=false){identity.GetUser(User);if(identity.IsDemo)return Ok(new{rows=Array.Empty<object>(),canEdit=false});if(f.Mode==2&&string.IsNullOrWhiteSpace(f.Batch))throw new ArgumentException("Ingresa la partida.");if(f.Mode==3&&f.From>f.To)throw new ArgumentException("Revisa el rango de fechas.");return Ok(new{rows=await repository.Search(f,ct,unfinished),canEdit=identity.CanRegister(User)});}
 public async Task<ServiceResult> Catalogs(CancellationToken ct){identity.GetUser(User);try{return Ok(await repository.Catalogs(ct));}catch(QualityEventConflict e){return Conflict(new BusinessProblem{Title=e.Message});}}
 public async Task<ServiceResult> Items(string batch,CancellationToken ct){identity.GetUser(User);try{return Ok(await repository.Items(batch,ct));}catch(QualityEventConflict e){return Conflict(new BusinessProblem{Title=e.Message});}}
 public async Task<ServiceResult> Save(QualityEventUpdate r,CancellationToken ct,bool unfinished=false){if(!identity.CanRegister(User)||!Actor.WriteRequested)throw new UnauthorizedAccessException();Validate(r);try{await repository.Save(r,ct,unfinished);return Ok(new{saved=true});}catch(QualityEventConflict e){return Conflict(new BusinessProblem{Title=e.Message});}}
 public static void Validate(QualityEventUpdate r){var errors=new List<System.ComponentModel.DataAnnotations.ValidationResult>();if(!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(r,new(r),errors,true))throw new ArgumentException(string.Join(" ",errors.Select(e=>e.ErrorMessage)));if(r.Action is not ("I" or "U" or "D")||r.Items.Length==0||r.Items.Select(i=>i.Sequence).Distinct().Count()!=r.Items.Length)throw new ArgumentException("Revisa la operación y los ítems seleccionados.");if(r.Action!="I"&&(r.Items.Length!=1||r.EventSequence<1))throw new ArgumentException("Selecciona un evento válido.");if(r.Auditor.Length<2)throw new ArgumentException("Selecciona el auditor.");if(r.Action!="D"&&r.Status=="R"&&string.IsNullOrWhiteSpace(r.Reason))throw new ArgumentException("Selecciona el motivo de rechazo.");if(r.Items.Any(i=>i.Kilos<0||decimal.Round(i.Kilos,2)!=i.Kilos))throw new ArgumentException("Los kilos deben ser positivos y tener hasta dos decimales.");}
}
